import numpy as np
def pe_input(k, mode='periodic', amplitude=1.):
    if mode=='constant': return amplitude
    if mode=='alternating': return amplitude if k%2==0 else -amplitude
    if mode=='burst' and not 0<=k<8: return 0.
    return amplitude*[1.,0.,-1.,0.][k%4]
def pe_design(mode='periodic', amplitude=1., count=64):
    return np.array([[pe_input(k,mode,amplitude), pe_input(k-1,mode,amplitude)] for k in range(count)])

